//! PrusaSlicer 設定バンドル/プロファイル (`*.ini`) の検出・カウント。
//!
//! `# generated by PrusaSlicer …` ヘッダ、`[print]`/`[filament]`/`[printer]`/
//! `[vendor]`/`[presets]` および `[print:名前]` のような名付きプリセット、
//! `key = value` 形式のスライサ設定行で構成される。
//!
//! ```
//! let cfg = b"# generated by PrusaSlicer 2.6\n\n[printer]\nnozzle_diameter = 0.4\n\
//!             printer_technology = FFF\nstart_gcode = G28\n\n[filament]\n\
//!             filament_type = PLA\nnozzle_temperature = 215\n";
//! assert!(izanagi_kit::prusaslicer::detect(cfg));
//! let c = izanagi_kit::prusaslicer::parse(cfg).unwrap();
//! assert_eq!(c.sections, 2);
//! assert_eq!(c.entries, 5);
//! assert_eq!(c.gcode_entries, 1);
//! assert_eq!(c.temperature_entries, 1);
//! ```

