/// セクション名の接頭辞として知られるもの (`[print:0.15 QUALITY]` 等)。
const SECTION_HEADS: &[&str] = &[
    "print",
    "filament",
    "printer",
    "vendor",
    "presets",
    "sla_print",
    "sla_material",
];

fn key_of(s: &str) -> Option<(&str, &str)> {
    let i = s.find('=')?;
    let k = s[..i].trim();
    if k.is_empty() || !k.bytes().all(|c| c.is_ascii_alphanumeric() || c == b'_') {
        return None;
    }
    Some((k, s[i + 1..].trim()))
}

/// カウント結果。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Counts {
    /// `[print]`/`[filament]`/`[print:名前]` 等のセクション数。
    pub sections: usize,
    /// `key = value` 行数。
    pub entries: usize,
    /// 既知キーによる行数。
    pub known_entries: usize,
    /// `*_gcode`/`start_gcode` 等の G-code 埋め込み行数。
    pub gcode_entries: usize,
    /// `*temperature*` キーの行数。
    pub temperature_entries: usize,
    /// `inherits` 継承指定の行数。
    pub inherits_entries: usize,
    /// `#`/`;` コメント行数 (generated ヘッダ含む)。
    pub comments: usize,
}

/// `b` が PrusaSlicer `*.ini` 形式かどうか。
#[must_use]
pub fn detect(b: &[u8]) -> bool {
    let text = match std::str::from_utf8(b) {
        Ok(t) => t,
        Err(_) => return false,
    };
    let text = strip_bom(text);
    // ジェネレータ署名は `#` コメント行にあるときだけ使う
    // — `key = value` の値中に同じ文字列があっても検出しない。
    if text
        .lines()
        .any(|l| l.trim_start().starts_with('#') && l.contains("generated by PrusaSlicer"))
    {
        return true;
    }
    let Some(c) = parse(b) else {
        return false;
    };
    c.entries >= 3 && c.known_entries >= 3
}

/// `b` を PrusaSlicer `*.ini` として解析し、行種別をカウントする。
#[must_use]
pub fn parse(b: &[u8]) -> Option<Counts> {
    let text = std::str::from_utf8(b).ok()?;
    let text = strip_bom(text);
    let mut c = Counts {
        sections: 0,
        entries: 0,
        known_entries: 0,
        gcode_entries: 0,
        temperature_entries: 0,
        inherits_entries: 0,
        comments: 0,
    };
    for line in text.lines() {
        let s = line.trim();
        if s.is_empty() {
            continue;
        }
        if s.starts_with('#') || s.starts_with(';') {
            c.comments += 1;
            continue;
        }
        if s.starts_with('[') {
            let inner = s
                .strip_prefix('[')
                .unwrap_or(s)
                .split(']')
                .next()
                .unwrap_or("")
                .trim();
            let head = inner.split(':').next().unwrap_or("");
            if SECTION_HEADS.contains(&head) {
                c.sections += 1;
            }
            continue;
        }
        if let Some((k, v)) = key_of(s) {
            if !KNOWN_KEYS.contains(&k) {
                continue;
            }
            c.entries += 1;
            c.known_entries += 1;
            if k.ends_with("gcode") || k == "start_gcode" || k == "end_gcode" {
                c.gcode_entries += 1;
            }
            if k.contains("temperature") {
                c.temperature_entries += 1;
            }
            if k == "inherits" || v == "inherits" {
                c.inherits_entries += 1;
            }
        }
    }
    if c.entries == 0 && c.sections == 0 {
        return None;
    }
    Some(c)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn detects_generated_header() {
        assert!(detect(
            b"# generated by PrusaSlicer 2.7.4 on 2024-01-01\n\n[printer]\n"
        ));
    }

    #[test]
    fn counts_entries() {
        let cfg = b"[print:0.20 QUALITY]\nlayer_height = 0.2\nperimeters = 3\n\
                    fill_density = 15%\n\n[filament:PLA]\nfilament_type = PLA\n\
                    bed_temperature = 60\ninherits = *COMMON*\n";
        assert!(detect(cfg));
        let c = parse(cfg).unwrap();
        assert_eq!(c.sections, 2);
        assert_eq!(c.entries, 6);
        assert_eq!(c.temperature_entries, 1);
        assert_eq!(c.inherits_entries, 1);
    }

    #[test]
    fn rejects_other_ini() {
        assert!(!detect(b"[section]\nfoo = bar\nbaz = quux\naaa = bbb\n"));
    }

    #[test]
    fn generator_marker_must_be_a_comment() {
        // The signature inside a value (not on a `#` line) must not trigger.
        assert!(!detect(
            b"[section]\nnote = generated by PrusaSlicer 2.6\nfoo = bar\nbaz = quux\n"
        ));
        assert!(detect(
            b"# generated by PrusaSlicer 2.6\n[print]\nfoo = bar\n"
        ));
    }

    #[test]
    fn utf8_bom_is_tolerated() {
        assert_eq!(strip_bom("\u{feff}x"), "x");
        assert_eq!(strip_bom("x"), "x");
    }
}
